const SEND_MESSAGE = '/network/dialogs/SEND-MESSAGE';

let initialState = {
    dialogsData: [
        {id: null, name: ''}
    ],
    messagesData: [
        {id: null, message: ''},
    ],
}

export const dialogsReducer = (state = initialState, action) => {
    let stateCopy = {
        ...state,
        messagesData: [...state.messagesData],
    }
    switch(action.type) {
        case SEND_MESSAGE: {
            stateCopy.messagesData.push({id: stateCopy.messagesData.length, message: action.message});
            return stateCopy;
        }
        default: {
            return stateCopy;
        }
    }
}

export const sendMessageActionCreator = (message) => ({type: SEND_MESSAGE, message});

export default dialogsReducer;