import React, {useState} from "react";
import s from './Paginator.module.css'

let Paginator = (props) => {
    let pagesCount = Math.ceil(props.totaItemsCount / props.pageSize);
    let items = [];

    for(let i = 1; i <= pagesCount; i++) {
        items.push(i)
    }

    let portionSize = props.portionSize
    let portionCount = Math.ceil(pagesCount / portionSize)
    let [portionNum, setPortionNum] = useState(1)
    let upperLimitPortionSize = (portionNum - 1) * portionSize + 1
    let lowerLimitPortionSize = portionNum * portionSize

    let chooseNextPage = () => {
        setPortionNum(portionNum+1)
        props.onPageChanged(upperLimitPortionSize+portionSize)
    }

    let choosePreviousPage = () => {
        setPortionNum(portionNum-1)
        props.onPageChanged(upperLimitPortionSize-portionSize)
    }

    return (
        <div className={s.wrapper}>
            {portionNum !== 1 && 
            <button className={s.btn} onClick={choosePreviousPage}>&#9668;</button>}
            <div className={s.pages}>
                {items
                .filter(p => p >= upperLimitPortionSize && p <= lowerLimitPortionSize)
                .map(p => {
                    return <span onClick={() => {props.onPageChanged(p)}} className={s.pageNumber + ' ' + (props.currentPage === p ? s.selectedPage : s.unSelectedPage)}>{p}</span>
                })}
            </div>
            {portionNum !== portionCount && 
            <button className={s.btn} onClick={chooseNextPage}>&#9658;</button>}
        </div>
    )
}

export default Paginator