import s from "./Friends.module.css"
import Friend from "./Friend/Friend.jsx"

const Friends = (props) => {
  let friendItem = props.friendsData.map(f => <Friend key={f.id} name={f.name}/>)
    return (
          <div className={s.wrapper}>
            <h3>Friends</h3>
            <div className={s.list}>
              {friendItem}
            </div>
          </div>
    )
}
export default Friends