import { profileAPI } from "../api/api";

const ADD_POST = 'network/profile/ADD-POST';
const SET_USER_PROFILE = 'network/profile/SET_USER_PROFILE';
const SET_STATUS = 'network/profile/SET_STATUS'
const DELETE_POST = 'network/profile/DELETE_POST'
const TOGGLE_IS_FETCHING = 'network/profile/TOGGLE_IS_FETCHING'

let initialState = {
    postData: [
        //{id: null, message: null, likesCount: null}
    ],
    profile: null,
    status: "",
    isFetching: false
}

export const profileReducer = (state = initialState, action) => {
    let stateCopy = {...state}
    stateCopy.postData = [...state.postData]
    switch(action.type) {
        case ADD_POST: {
            let newPost = {
                id: state.postData.length + 1,
                message: action.postMessage,
                likesCount: 0
            };
            return {
                ...state,
                postData: [...state.postData, newPost],
            }
        }
        case SET_USER_PROFILE: {
            return {
                ...state,
                profile: action.profile
            }
        }
        case SET_STATUS: {
            return {
                ...state,
                status: action.status
            }
        }
        case DELETE_POST: {
            return {...state, postData: state.postData.filter(p => p.id !== action.postId)}
        }
        case TOGGLE_IS_FETCHING: {
            return {...state, isFetching: action.isFetching}
        }
        default: {
            return state;
        }
    }
    }

export const addPost = (postMessage) => ({type: ADD_POST, postMessage});
export const setUserProfile = (profile) => ({type:SET_USER_PROFILE, profile})
export const setStatus = (status) => ({type:SET_STATUS, status})
export const deletePost = (postId) => ({type: DELETE_POST, postId})
export const tooggleIsFetching = (isFetching) => ({type: TOGGLE_IS_FETCHING, isFetching})

export const getProfile = (userId) => async (dispatch) => {
    let response = await profileAPI.getProfile(userId)

    dispatch(setUserProfile(response.data))
}
export const getStatus = (userId) => async (dispatch) => {
    let response = await profileAPI.getStatus(userId)

    dispatch(setStatus(response.data))
}
export const updateStatus = (status) => async (dispatch) => {
    dispatch(tooggleIsFetching(true))
    let response = await profileAPI.updateStatus(status)

    if(response.data.resultCode === 0) {
        dispatch(setStatus(status))
        dispatch(tooggleIsFetching(false))
    }
    
}

export default profileReducer;