import React from 'react'
import { Field, reduxForm } from 'redux-form'
import { Input } from '../common/FormsControls/FormsControls'
import { maxLengthCreator, requiredField } from '../../utils/validators/validators'
import s from '../common/FormsControls/FormsContol.module.css'

const maxLength50 = maxLengthCreator(50)

const LoginForm = (props) => {
    return (
        <form onSubmit={props.handleSubmit} >
            <div>
                <Field placeholder='email' component={Input} name={'email'} validate={[requiredField, maxLength50]}/>
            </div>
            <div>
                <Field type='password' placeholder='password' component={Input} name={'password'} validate={[requiredField, maxLength50]} />
            </div>
            <div>
                <Field type={"checkbox"} component={Input} name={'rememberMe'}/> remember me
            </div>
            {props.error && <div className={s.formSummaryError}>
                {props.error}
            </div>}
            <div>
                <button>Login</button>
            </div>
        </form>
    )
}

const LoginReduxForm = reduxForm({
    form: 'login'
})(LoginForm)

export default LoginReduxForm