import { usersAPI, followAPI } from "../api/api";

const FOLLOW = 'network/users/FOLLOW';
const UNFOLLOW = 'network/users/UNFOLLOW'
const SET_USERS = 'network/users/SET_USERS'
const SET_CURRENT_PAGE = 'network/users/SET_CURRENT_PAGE'
const SET_TOTAL_USERS_COUNT = 'network/users/SET_TOTAL_USERS_COUNT'
const TOGGLE_IS_FETCHING = 'network/users/TOGGLE_IS_FETCHING'
const TOGGLE_IS_FOLLOWING_PROGRESS = 'network/users/TOGGLE_IS_FOLLOWING_PROGRESS'

let initialState = {
    users: [],
    pageSize: 4,
    totalUsersCount: 0,
    currentPage: 1,
    isFetching: true,
    followingInProgress: []
}

export const userReducer = (state = initialState, action) => {
    switch(action.type) {
        case FOLLOW:
            return {
                ...state,
                users: state.users.map( u => {
                    if(u.id === action.userId) {
                        return {...u, followed: true}
                    }
                    return u
                } ),
            }
        case UNFOLLOW:
            return {
                ...state,
                users: state.users.map( u => {
                    if(u.id === action.userId) {
                        return {...u, followed: false}
                    }
                    return u
                })
            }
        case SET_USERS:
            return {...state, users: action.users}
        case SET_CURRENT_PAGE:
            return {...state, currentPage: action.currentPage}
        case SET_TOTAL_USERS_COUNT:
            return {...state, totalUsersCount: action.totalUsersCount}
        case TOGGLE_IS_FETCHING:
            return {...state, isFetching: action.isFetching}
        case TOGGLE_IS_FOLLOWING_PROGRESS:
            return {
                ...state, 
                followingInProgress: action.inProgress 
                ? [...state.followingInProgress, action.userId] 
                : state.followingInProgress.filter(id => id !== action.userId)
                }
        default:
            return state;
    }
}
export const accessFollow = (userId) => ({type: FOLLOW, userId})
export const accessUnFollow = (userId) => ({type: UNFOLLOW, userId})
export const setUsers = (users) => ({type: SET_USERS, users})
export const setCurrentPage = (currentPage) => ({type: SET_CURRENT_PAGE, currentPage})
export const setTotalUsersCount = (totalUsersCount) => ({type: SET_TOTAL_USERS_COUNT, totalUsersCount})
export const toggleIsFetching = (isFetching) => ({type:TOGGLE_IS_FETCHING, isFetching})
export const toggleFollowingProgress = (inProgress, userId) => ({type:TOGGLE_IS_FOLLOWING_PROGRESS, inProgress, userId})

export const requestUsers = (currentPage,pageSize) => async (dispatch) => {
    dispatch(toggleIsFetching(true))
    dispatch(setCurrentPage(currentPage))
    
    let response = await usersAPI.getUsers(currentPage, pageSize)

    dispatch(toggleIsFetching(false))
    dispatch(setUsers(response.data.items));
    dispatch(setTotalUsersCount(response.data.totalCount))
}
export const unFollow = (id) => async (dispatch) => {
    dispatch(toggleFollowingProgress(true, id))

    let response = await followAPI.unFollow(id)

    if(response.data.resultCode === 0) {
        dispatch(accessUnFollow(id))
    }
    dispatch(toggleFollowingProgress(false, id))
}
export const follow = (id) => async (dispatch) => {
    dispatch(toggleFollowingProgress(true, id))

    let response = await followAPI.follow(id)

    if(response.data.resultCode === 0) {
        dispatch(accessFollow(id))
    }
    dispatch(toggleFollowingProgress(false, id))
}
export const setPage = (pageNum) => (dispatch) => {
    dispatch(setCurrentPage(pageNum))
}

export default userReducer