import React from 'react'
import s from './Users.module.css'
import userPhoto from '../../assets/img/user.png'
import { NavLink } from "react-router-dom"
import Paginator from '../common/Paginatior/Paginator'

let Users = (props) => {

    return (
        <div>
            <div className={s.info__wrapper}>
                {props.users.map(u => <div key={u.id}>
                    <div className={s.imgAndButton}>
                        <div>
                            <NavLink to={'/profile/' + u.id}>
                                <img className={s.userPhoto} src={u.photos.small != null ? u.photos.small : userPhoto} alt="" />
                            </NavLink>
                        </div>
                        <div>
                            {u.followed ? 
                            <button className={s.followButton} disabled={props.followingInProgress.some(id => id === u.id)} onClick={() => {
                                props.unFollow(u.id)
                                }}>unfollow</button> : 
                            <button className={s.followButton} disabled={props.followingInProgress.some(id => id === u.id)} onClick={() => {
                                props.follow(u.id)   
                                }}>follow</button>}
                        </div>
                    </div>
                    <div className={s.mainInfoBlock}>
                        <div className={s.userName}>{u.name}</div>
                        <div className={s.status}>{u.status ?? 'His status'}</div>
                    </div>
                </div>)}
            </div>
            <Paginator  totaItemsCount={props.totalUsersCount}
                        pageSize={props.pageSize}
                        onPageChanged={props.onPageChanged}
                        currentPage={props.currentPage}
                        setPage = {props.setPage}
                        portionSize = {10} />
        </div>
    )
}

export default Users